export type ConnectionState = 'LIVE' | 'DELAYED' | 'RECONNECTING' | 'OFFLINE' | 'REPLAY';
export type PositionQuality = 'exact' | 'estimated' | 'unavailable';
export interface RuntimeCapabilities {timing:boolean;intervals:boolean;tires:boolean;weather:boolean;raceControl:boolean;radioMetadata:boolean;position:boolean;telemetry:boolean;radio?:boolean}
export interface LiveHealth {status:'CONNECTED'|'DELAYED'|'STALE'|'RECONNECTING'|'OFFLINE';transport:string;dataAgeMs:number|null;sourceTimestamp?:number|null;sessionAvailability:string;channels?:Record<string,{sourceTimestamp:number|null;ageMs:number|null;state:string;delayedMs:number;staleMs:number}>}
export type Gap = number | string | null;
export interface LocationState { at:number; x:number; y:number; interpolated:boolean }
export interface WeatherState { at:number|null; air:number|null; track:number|null; humidity:number|null; pressure:number|null; windSpeed:number|null; windDirection:number|null; rainfall:number|null }
export interface RaceControlEvent { at:number; category:string; message:string; flag:string|null; scope:string|null; number:number|null; lap:number|null; sector:number|null }
export interface Lap { number:number; at:number; lap:number; seconds:number|null; completedAt:number|null; pitOut:boolean; sector1:number|null; sector2:number|null; sector3:number|null }
export interface Session {key:number|null; meetingKey:number|null; year:number|null; name:string; type:string; circuit:string; start:number|null; end:number|null; scheduledStart:number|null;currentLap?:number|null;totalLaps?:number|null;status?:string|null;circuitKey?:number|null;round?:number|null;slug?:string}
export interface DriverState {number:number; abbreviation:string; name:string; team:string; color:string; position:number|null; positionAt:number|null; gap:Gap; interval:Gap; gapAt:number|null; currentLap:number|null; completedLap:number|null; lastLap:number|null; bestLap:number|null; compound:string|null; tyreAge:number|null; pitStops:number|null; pitStatus:string|null; location:LocationState|null; radio:{at:number|null; url?:string|null;reference?:string;driverNumber?:number}[]; telemetry:TelemetryState|null;positionQuality?:PositionQuality;estimatedLocation?:LocationState|null;trackProgress?:number|null;pitIn?:boolean|null;pitOut?:boolean|null;pitDuration?:number|null;retired?:boolean|null}
export interface TelemetryState { at:number; speed:number|null; drs:number|null; throttle:number|null; brake:number|null; gear:number|null; rpm:number|null }
export interface RaceState {mode:'live'|'replay'|'simulated-live'|'capture-replay';session:Session;timestamp:number|null;source:string;fetchedAt:string|null;connection:ConnectionState;drivers:DriverState[];weather:WeatherState|null;control:RaceControlEvent[];status:string;fastestLap:(Pick<Lap,'number'|'seconds'|'completedAt'|'pitOut'>&{lap:number|null;at:number|null;driver:string;name:string;team:string;color:string})|null;simulation?:{playing:boolean;speed:number;generation:number};capabilities?:RuntimeCapabilities;positionQuality?:PositionQuality;positionPolicy?:{estimatedEnabled:boolean;defaultEnabled:boolean;prototype:boolean;exactSourceTimestamp:number|null};health?:LiveHealth;playback?:{kind:'capture';captureId:string;start:number;end:number;cursor:number};active?:boolean;reason?:string|null}
export interface ChampionshipState {season:number;kind:'Race'|'Sprint';drivers:{number:number;confirmed:number;projectedEarned:number;projectedTotal:number}[];source:string;at:number;assumptions:string[]}
export interface ReplayDataset { version:number;mode:'replay';session:Session;drivers:{number:number;abbreviation:string;name:string;team:string;color:string;locations:[number,number,number][];positions:{at:number;position:number}[];intervals:{at:number;gap:Gap;interval:Gap}[];laps:Lap[];completedLaps:Lap[];stints:{lapStart:number;lapEnd:number|null;compound:string|null;ageStart:number|null}[];pits:{at:number;lap:number|null;laneSeconds:number|null;stopSeconds:number|null}[];radio:{at:number;url:string|null}[];telemetry:TelemetryState[]}[];weather:WeatherState[];control:RaceControlEvent[];track:{driver:number|null;lap:number|null;at:number|null;fitBounds?:CoordinateBounds|null;projectedBounds?:CoordinateBounds|null;points:[number,number][];rotation:number;corners:{number:number;x:number;y:number}[];sector1:LocationState|null;sector2:LocationState|null;cornerSource:string|null;drsZones:unknown[]};provenance:{endpoint:string;url:string;fetchedAt:string;sha256:string;count:number|null;stale:boolean}[];quality:{invalid:Record<string,number>;unavailable:string[];locationCount:number};fetchedAt:string;capabilities?:ReplayCapabilities;indexes?:{version:number;lapBoundaries:{lap:number;at:number;number:number;leader:boolean}[];strategy:string};validation?:ReplayValidation;import?:{availability:Record<string,ReplaySourceAvailability>;metrics:Record<string,number>;legacyMigration:boolean;importedAt:string}}

export interface CoordinateBounds {minX:number;maxX:number;minY:number;maxY:number}
export interface ReplayCapabilities extends RuntimeCapabilities {pit:boolean}
export interface ReplaySourceAvailability {status:'RECEIVED'|'EMPTY'|'ERROR'|'NOT REQUESTED'|'PARTIAL';count?:number;reason?:string;stale?:boolean}
export interface ReplayValidation {status:'VALID'|'PARTIAL'|'INVALID';reasons:string[];warnings:string[];missingDrivers?:{number:number;channel:string}[];invalid?:Record<string,number>;counts:Record<string,number>;bounds?:CoordinateBounds|null;capabilities:Partial<ReplayCapabilities>;comparison?:unknown;timestampRange?:{start:number;end:number};checkedAt?:string}
export interface ReplayManifestEntry {season:number;round:number|null;grandPrix:string;slug:string;session:string;sessionKey:number;meetingKey:number;circuit:string;date:string;drivers:number;laps:number;locations:number;capabilities:ReplayCapabilities;availability:Record<string,ReplaySourceAvailability>;validation:'VALID'|'PARTIAL'|'INVALID';missing:string[];cacheVersion:number;sha256:string;bytes:number;importedAt:string;metrics:Record<string,number>}

// Season information is separate from live RaceState; all times are UTC epoch ms.
export interface SeasonDriver {id:string|null;name:string;abbreviation:string|null;number:number|null;nationality:string|null}
export interface SeasonTeam {id:string|null;name:string;nationality:string|null;color:string}
export interface Meeting {season:number;round:number;slug:string;name:string;country:string|null;locality:string|null;circuit:{id:string|null;name:string|null};date:string|null;start:number|null;sessions:{name:string;start:number|null}[]}
export interface Standing {id:string;position:number|null;points:number|null;wins:number|null;change:number|null;driver:SeasonDriver|null;team:SeasonTeam;teams:SeasonTeam[]}
export interface SeasonRaceResult {position:number|null;positionText:string|null;driver:SeasonDriver;team:SeasonTeam;number:number|null;grid:number|null;laps:number|null;points:number|null;time:string|null;timeMillis:number|null;status:string|null;classification:string;q1:string|null;q2:string|null;q3:string|null;fastest:{rank:number|null;lap:number|null;time:string|null}|null}
export interface WeekendResult extends Meeting {kind:'race'|'sprint'|'qualifying';results:SeasonRaceResult[]}
export interface PointsProgression {rounds:{round:number;name:string;slug:string;stage:'RACE COMPLETE'|'SPRINT ONLY';drivers:Record<string,number|null>;constructors:Record<string,number|null>}[];drivers:(SeasonDriver&{team:SeasonTeam;color:string})[];constructors:SeasonTeam[];complete:boolean;reconciliation:{matches:boolean;checked:number;mismatches:{kind:string;id:string;calculated:number|null;confirmed:number}[]};rule:{season:number;race:number[];sprint:number[];fastestLapBonus:number;method:string;source:string}}
export interface Season {season:number;schedule:Meeting[];standings:{round:number;drivers:Standing[];constructors:Standing[]};races:WeekendResult[];sprints:WeekendResult[];progression:PointsProgression;errors:Record<string,string>;source:string;fetchedAt:string;stale:boolean;provenance:{source:string;url:string;fetchedAt:string;sha256:string;stale:boolean}[]}
